-- ARROWQUEST(AU)[32+64]-V15.01
-- Do not edit this file. Any change breaks the decoder.
local _fcaqmk = 195
local _qgshmg = 69
local _deolrr = 255
local _rxhvgl = ""

local _cwhged = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _chgkra(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _toohbu(d)
	d = d:gsub("[^" .. _cwhged .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_cwhged:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _uafall = _toohbu(_rxhvgl)
local _ftdbkq = { _fcaqmk, _qgshmg, _deolrr }
local _wkosod = {}
for i = 1, #_uafall do
	_wkosod[i] = string.char(_chgkra(_uafall:byte(i), _ftdbkq[(i - 1) % 3 + 1]))
end

local _klbfiw = load or loadstring
local _fcrypg, _lgcsuc = _klbfiw(table.concat(_wkosod), "=w")
if not _fcrypg then
	gg.alert("Corrupted file: " .. tostring(_lgcsuc))
	os.exit()
end
_fcrypg()
